def read_r_binary_doubles(path: Path) -> list[float]:
    """Little-endian IEEE-754 doubles as written by R's writeBin()."""
    import struct

    data = path.read_bytes()
    if len(data) % 8:
        raise ReproduceError(f"fixture {path} has {len(data)} bytes (not a multiple of 8)")
    return list(struct.unpack("<%dd" % (len(data) // 8), data))


def port_stream_matches_r_fixture() -> tuple[bool, str]:
    """Exact-compare the Python RNG port with R's own rnorm stream fixture."""
    from r_rng_fallback import RRandom

    fixture = data_cache() / "rnorm_49998_seed1863.bin"
    if not fixture.exists():
        return False, "fixture missing"
    r_vec = read_r_binary_doubles(fixture)
    py_vec = RRandom(SEED).rnorm(len(r_vec))
    same = py_vec == r_vec  # exact float equality == bit-identical here
    return same, "bit-identical" if same else "stream mismatch"


def validate_port_against_r(rscript: str) -> tuple[bool, str]:
    cache = data_cache()
    fixture = cache / "rnorm_49998_seed1863.bin"
    if not fixture.exists():
        r = run([rscript, "--vanilla", "r_dump_stream.R", "49998", str(SEED), str(fixture)], timeout=600)
        if r.returncode != 0 or not fixture.exists():
            return False, "fixture generation failed"
    return port_stream_matches_r_fixture()


def port_counts(n: int) -> dict:
    import compute_counts

    return compute_counts.counts_for(n, seed=SEED)
